	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["After the farm's keys: the {object:177289} stands just south-west of the farmhouse, and its Cauldron Lord beside it carries the key."] = "Depois das chaves da fazenda: o {object:177289} fica logo a sudoeste da casa da fazenda, e o Mestre da Caldeira ao lado dele carrega a chave.",
	-- ["Andorhal Watches"] = "Relógios de Andorhal",
	-- ["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "Volte para o norte até {area:202}: o caldeirão agora oferece a própria tarefa. Os carniçais por perto deixam cair Intensificadores Somáticos.",
	-- ["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Volte ao acampamento de {npc:7775}, logo a sudeste de {npc:7765}: o {item:11242} rende três Elixires de Videre. Guarde-os: {npc:9298} fica com um, e {npc:9299} em {area:976} só aparece para quem tiver bebido um.",
	-- ["Below ground"] = "No subterrâneo",
